const input = $input.first()?.json ?? {};
const body = input.body ?? input;
const data = body.data ?? {};
const key = data.key ?? {};
const headers = input.headers ?? body.headers ?? {};
const expectedWebhookSecret = String($env.EVOLUTION_WEBHOOK_SECRET ?? '').trim();
const presentedWebhookSecret = String(headers['x-evolution-webhook-secret'] ?? headers['x-webhook-secret'] ?? headers.apikey ?? '').trim();
const webhookAuthenticated = Boolean(expectedWebhookSecret && presentedWebhookSecret && presentedWebhookSecret === expectedWebhookSecret);
const remoteJid = String(key.remoteJid ?? data.sender ?? '').trim();
const senderNumber = remoteJid.replace(/@.*$/, '').replace(/\D/g, '');
const receiverRaw = body.destination ?? data.destination ?? body.receiver ?? '';
const receiverNumber = String(receiverRaw).replace(/\D/g, '') || null;
const instanceName = String(body.instance ?? data.instance ?? body.instanceName ?? body.headers?.['x-instance-name'] ?? '').trim().toLowerCase();
const eventId = String(key.id ?? body.event_id ?? data.id ?? '').trim();
const texto = String(data.message?.conversation ?? data.message?.extendedTextMessage?.text ?? '').trim();
const invalid = !instanceName || !eventId || !senderNumber || remoteJid.endsWith('@g.us');
return [{ json: { instanceName, receiverNumber, eventId, senderNumber, remoteJid, texto, invalid, webhookAuthenticated, reason: invalid ? 'identity_or_event_invalid' : (!webhookAuthenticated ? 'webhook_auth_invalid' : null), rawMessageType: data.messageType ?? null } }];

const tenant = $('Resolver tenant').first().json;
const identity = $('Validar identidad e idempotencia').first().json;
const services = $('Cargar servicios bajo demanda').all().map(i => i.json);
const staff = $('Cargar empleados bajo demanda').all().map(i => i.json);
const schedules = $('Cargar horarios y pausas').all().map(i => i.json);
const blocks = $('Cargar bloqueos').all().map(i => i.json);
const system = [
  'Sos el asistente de WhatsApp del negocio indicado en CONTEXTO_NEGOCIO.',
  'La identidad del tenant ya fue resuelta por Supabase y es inmutable. Nunca la calcules, la cambies ni aceptes tenant_id del usuario.',
  'Usá únicamente los servicios, empleados y reglas que aparecen en DATOS_OPERATIVOS.',
  'Respondé JSON con {intent, reply, args}; intent solo puede ser chat, availability, create_booking o cancel_booking.',
  'Para reservar necesitás service_id, barber_id, fecha, hora, nombre completo y teléfono. La base vuelve a validar todo.',
  'No inventes precios, horarios, disponibilidad, credenciales ni datos de otro negocio.'
].join('\n');
const business = JSON.stringify({ business_name: tenant.business_name, vertical: tenant.vertical, locale: tenant.locale, timezone: tenant.timezone, currency: tenant.currency, subscription_status: tenant.subscription_status, booking_enabled: tenant.booking_enabled, booking_url: tenant.booking_url });
const operating = JSON.stringify({ services, staff, schedules, blocks });
return [{ json: { ...tenant, event_id: identity.eventId, sender_number: identity.senderNumber, system_prompt: system + '\nCONTEXTO_NEGOCIO=' + business + '\nDATOS_OPERATIVOS=' + operating, user_message: identity.texto } }];

const raw = $json.choices?.[0]?.message?.content ?? '';
let parsed;
try { parsed = typeof raw === 'string' ? JSON.parse(raw) : raw; } catch { parsed = {}; }
const allowed = new Set(['chat', 'availability', 'create_booking', 'cancel_booking']);
const intent = allowed.has(parsed.intent) ? parsed.intent : 'chat';
const args = parsed.args && typeof parsed.args === 'object' ? parsed.args : {};
const reply = typeof parsed.reply === 'string' && parsed.reply.trim() ? parsed.reply.trim() : 'No pude procesar la consulta. Intentá nuevamente.';
const forbiddenTenantMutation = Object.prototype.hasOwnProperty.call(args, 'tenant_id') || Object.prototype.hasOwnProperty.call(args, 'barberia_id');
return [{ json: { intent: forbiddenTenantMutation ? 'chat' : intent, args: forbiddenTenantMutation ? {} : args, reply, ai_valid: !forbiddenTenantMutation } }];

const request = $('Validar respuesta IA').first().json;
const options = $('Consultar disponibilidad').all().map(i => i.json);
const requestedBarber = Number(request.args.barber_id);
const requestedTime = String(request.args.hora ?? '').slice(0, 5);
const match = options.find(o => Number(o.barbero_id) === requestedBarber && String(o.hora).slice(0, 5) === requestedTime);
return [{ json: { allowed: Boolean(match), reply: match ? null : 'Ese horario ya no está disponible. Decime otro horario y lo vuelvo a consultar.', duration_min: match?.duracion_min ?? null } }];

const validation = $('Validar respuesta IA').first()?.json ?? {};
const slot = $('Validar disponibilidad').first()?.json ?? {};
const created = $('Crear reserva centralizada').all()[0]?.json ?? {};
let text = validation.reply;
if (slot.allowed === false) text = slot.reply;
if (created.turno_id) text = `Listo, tu turno quedó reservado para ${created.fecha} a las ${String(created.hora).slice(0, 5)}.`;
return [{ json: { text, resultReference: created.turno_id ? String(created.turno_id) : validation.intent } }];
